import { useCallback, useRef } from "react"
import { TrackballControls } from "@react-three/drei"
import debounce from "lodash.debounce"
import throttle from "lodash.throttle"
import { useControls } from "leva"

import { gridSpacing } from "../../constants"
import {
  cameraOverallProgress,
  getCameraEndPos,
  getCameraStartPos,
  isCameraAtMinOrMaxPosZ,
} from "./cameraUtils"
import useStore, {
  setCameraMoving,
  setCameraHalt,
  setCameraProgress,
  setCameraPositionBounds,
  setChapterStarted,
} from "../../store"

const Controls = () => {
  const cameraControls = useControls("controls", {
    activatePanning: false,
    activateRotating: false,
    activateZooming: true,
    zoomSpeed: 1,
  })

  const cameraControlsRef = useRef()
  const { usesTouch } = useStore(state => state.clientProfile)
  const zoomSpeedReduction = usesTouch ? 0.1 : 1

  const chapterTransitionActive = useStore(
    state => state.chapterTransitionActive
  )

  const handleOnTrackballEnd = useCallback(setCameraHalt, [])

  const handleOnTrackballStart = useCallback(() => {
    setCameraMoving()

    const progress = cameraOverallProgress(
      cameraControlsRef?.current?.object?.position?.z - gridSpacing.z,
      getCameraStartPos() - gridSpacing.z
    )

    setChapterStarted()
    setCameraProgress(Math.round(progress))
  }, [])

  const handleOnTrackballChange = () => {
    const { atMaxPos, atMinPos } = isCameraAtMinOrMaxPosZ(
      cameraControlsRef?.current?.object?.position?.z
    )

    setCameraPositionBounds(atMinPos, atMaxPos)
  }

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const delayedOnStart = useCallback(throttle(handleOnTrackballStart, 200), [])
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const delayedOnChange = useCallback(
    throttle(handleOnTrackballChange, 100),
    []
  )
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const delayedOnEnd = useCallback(debounce(handleOnTrackballEnd, 300), [])

  return (
    <TrackballControls
      ref={cameraControlsRef}
      regress={true}
      zoomSpeed={cameraControls.zoomSpeed * zoomSpeedReduction}
      minDistance={getCameraEndPos()}
      maxDistance={getCameraStartPos()}
      onChange={delayedOnChange}
      onStart={delayedOnStart}
      onEnd={delayedOnEnd}
      noZoom={!cameraControls.activateZooming || chapterTransitionActive}
      noPan={!cameraControls.activatePanning}
      noRotate={!cameraControls.activateRotating}
    />
  )
}

export default Controls
