import { ShaderMaterial, UniformsUtils, UniformsLib } from "three"
import { extend } from "@react-three/fiber"

class ImageMaterial extends ShaderMaterial {
  constructor() {
    super({
      vertexShader: `
        #include <fog_pars_vertex>

        precision mediump float;

        varying vec2 vUv;
        varying float vPosZ;

        uniform float uTime;
        uniform float uProg;
        uniform float uCameraDistanceZ;

        void main() {
          #include <begin_vertex>
          #include <project_vertex>
          #include <fog_vertex>

          vec3 pos = position;
          
          if (pos.z < uCameraDistanceZ && uCameraDistanceZ < 30.0) {
            float power = clamp(uCameraDistanceZ,1.0, 5.0);
            pos.z += sin(pos.y * power + uTime) * .1 * uProg;
          }
          
          vUv = uv;
          vPosZ = pos.z;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.);
        }
      `,
      fragmentShader: `
        precision mediump float;
        varying vec2 vUv;
        varying float vPosZ;

        #include <fog_pars_fragment>

        uniform sampler2D uTexture;
        uniform float uProg;
        uniform float uCameraDistanceZ;


        void main() {
          if (vPosZ < uCameraDistanceZ && uCameraDistanceZ < 48.0) {
            float r = texture2D(uTexture, vUv + vPosZ * 0.05).r;
            float g = texture2D(uTexture, vUv + vPosZ * -0.1).g;
            float b = texture2D(uTexture, vUv + vPosZ * 0.2).b;

            gl_FragColor = vec4(vec3(r, g, b), 1.0);
          } else {
            gl_FragColor = vec4(gl_FragColor.rgb, 1.0);
          }

          #include <fog_fragment>

        }
      `,
      uniforms: {
        uTime: { value: 0.0 },
        uTexture: { value: null },
        uProg: { value: 1.0 },
        uCameraDistanceZ: { value: 0.0 },
        ...UniformsUtils.merge([UniformsLib["fog"]]),
      },
      fog: true,
    })
  }

  set map(value) {
    this.uniforms.uTexture.value = value
  }

  get map() {
    return this.uniforms.uTexture.value
  }
}

extend({ ImageMaterial })
