import { useSpring, animated } from "react-spring"

import useStore from "../../store"
import "./ChapterTitle.css"
import { useContent } from "../../common/content"
import { easings } from "./../../constants"

const ChapterTitle = ({ show }) => {
  const chapterTitleLabel = useContent({ path: "experience/chapterTitleLabel" })
  const chapterNames = useContent({ path: "experience/chapterNames" })
  const chapter = useStore(state => state.chapter)

  const titleTransition = useSpring({
    opacity: show ? 1 : 0,
    y: show ? 0 : 32,
    config: { easing: easings.easeOutQuad },
    delay: show ? 1000 : 0,
  })

  const subTitleTransitions = useSpring({
    opacity: show ? 1 : 0,
    y: show ? 0 : 32,
    config: { easing: easings.easeOutQuad },
    delay: show ? 1300 : 0,
  })

  return (
    <div className="chapter-title">
      <div className="overflow-hidden">
        <animated.h3 style={titleTransition} className="chapter-title__label">
          {chapterTitleLabel}
        </animated.h3>
      </div>
      <div className="overflow-hidden">
        <animated.h2
          style={subTitleTransitions}
          className="chapter-title__title"
        >
          {chapterNames[chapter.index - 1]}
        </animated.h2>
      </div>
    </div>
  )
}

export default ChapterTitle
