import { useEffect, useState } from "react"
import { useSpring, animated } from "react-spring"

import useStore, {
  goToNextChapter,
  goToPreviousChapter,
  setChapterTransition,
  addToActiveLoading,
  removeFromActiveLoading,
} from "./../../store"
import { content, utils } from "./../../common"
import { allChaptersCount, chapterTransitionTime } from "./../../constants"
import "./ChapterSwitch.css"

const ChapterSwitch = () => {
  const label = content.useContent({ path: "experience/chapterSwitch" })
  const [showContent, setShowContent] = useState(false)

  const cameraAtMaxPos = useStore(state => state.cameraAtMaxPos)
  const cameraAtMinPos = useStore(state => state.cameraAtMinPos)
  const chapterTransitionActive = useStore(
    state => state.chapterTransitionActive
  )
  const { index: chapterIndex } = useStore(state => state.chapter)
  const chapterStarted = useStore(state => state.chapterStarted)

  const isFirstChapter = chapterIndex === 1
  const isLastChapter = chapterIndex === allChaptersCount
  const hasNext = chapterIndex + 1 <= allChaptersCount
  const hasPrevious = chapterIndex > 1

  const showAnyButton = chapterStarted && !chapterTransitionActive
  const showNextButton =
    showAnyButton && !isLastChapter && cameraAtMinPos && hasNext
  const showPrevButton =
    showAnyButton && !isFirstChapter && cameraAtMaxPos && hasPrevious

  utils.useTimeout(
    () => {
      setShowContent(false)

      if (showNextButton) {
        goToNextChapter()
      } else if (showPrevButton) {
        goToPreviousChapter()
      }

      setChapterTransition(true)
    },
    showNextButton || showPrevButton ? chapterTransitionTime : null
  )

  useEffect(() => {
    if (showNextButton || showPrevButton) {
      setShowContent(true)
      addToActiveLoading("chapterSwitch")
    } else {
      setShowContent(false)
      removeFromActiveLoading("chapterSwitch")
    }
  }, [showNextButton, showPrevButton])

  return (
    <div className="chapter-switch">
      <Button
        show={showContent}
        label={label}
        onClick={() => setShowContent(false)}
      />
    </div>
  )
}

const Button = ({ label, onClick, show }) => {
  const [styles, api] = useSpring(() => ({ opacity: 0 }))

  useEffect(() => {
    api.start({ opacity: show ? 1 : 0, y: show ? 0 : 32 })
  }, [show, api])

  return (
    <div className="overflow-hidden">
      <animated.button
        style={styles}
        className="chapter-switch__button"
        onClick={onClick}
      >
        {label}
      </animated.button>
    </div>
  )
}

export default ChapterSwitch
