import { useTexture } from "@react-three/drei"
import { useMemo } from "react"
import { PlaneBufferGeometry } from "three"
import { useSpring, animated } from "@react-spring/three"

import * as constants from "./../../constants"
import Image from "./image"
import useStore, { setChapterTransition } from "./../../store"

const Chapter = ({ annotations = [], images = [], imageSize }) => {
  const textures = useTexture([
    ...images.map(image => {
      return image.default
    }),
  ])

  const plane = useMemo(
    () => new PlaneBufferGeometry(imageSize, imageSize, 8, 8),
    [imageSize]
  )

  return (
    <>
      {[...Array(constants.itemsPerRow).keys()].map(row =>
        [...Array(constants.itemPerColumn).keys()].map(column => {
          const currPosX = column + constants.gridSpacing.x * column
          const currPosY = row + constants.gridSpacing.y * row
          const aggegratedIterator = column + row * constants.itemPerColumn

          return (
            <Segment
              key={`${row}-${column}-${constants.gridSpacing.x}-${constants.gridSpacing.y}-${imageSize}`}
              enterAnimationDelay={
                constants.itemPerColumn * constants.itemsPerRow -
                aggegratedIterator
              }
              onEnterAnimationFinished={
                aggegratedIterator + 1 ===
                constants.itemPerColumn * constants.itemsPerRow
                  ? () => setChapterTransition(false)
                  : undefined
              }
              position={[currPosX, currPosY, 0]}
              imageSize={imageSize}
              geometry={plane}
              annotations={annotations.slice(
                aggegratedIterator * constants.itemsPerSegment,
                aggegratedIterator * constants.itemsPerSegment +
                  constants.itemsPerSegment +
                  1
              )}
              textures={textures.slice(
                aggegratedIterator * constants.itemsPerSegment,
                aggegratedIterator * constants.itemsPerSegment +
                  constants.itemsPerSegment +
                  1
              )}
            />
          )
        })
      )}
    </>
  )
}

function Segment(props) {
  const inExperience = useStore(state => state.inExperience)

  const { z } = useSpring({
    z: inExperience ? 0 : constants.gridSpacing.z / 2,
    from: { z: constants.gridSpacing.z / 2 },
    delay: props.enterAnimationDelay * 100,
    config: { duration: 700, easing: constants.easings.easeOutQuad },
    onRest: state => {
      if (state.value.z === 0 && props.onEnterAnimationFinished) {
        props?.onEnterAnimationFinished()
      }
    },
  })

  return (
    <animated.group position-z={z} visible={inExperience}>
      {[...Array(constants.itemsPerSegment).keys()].map(index => {
        return (
          <Image
            {...props}
            key={index}
            delay={props.animationDelay}
            position-z={index * constants.gridSpacing.z}
            geometry={props.geometry}
            text={props.annotations[index]}
            texture={props.textures[index]}
          />
        )
      })}
    </animated.group>
  )
}

export default Chapter
