import { Text } from "@react-three/drei"
import { useFrame, useThree } from "@react-three/fiber"
import { useEffect, useRef } from "react"
import { useSpring, config } from "@react-spring/three"

import font from "./../../../assets/Jost/static/Jost-Medium.ttf"
import "./Material"
import useStore from "./../../../store"

const formatLabel = text => {
  return text.substring(text.lastIndexOf("/"), text.lastIndexOf("."))
}

const Image = ({ geometry, text, texture, opacity = 1, ...props }) => {
  const mesh = useRef()
  const { camera } = useThree()
  const cameraMoving = useStore(state => state.cameraMoving)
  const material = useRef()
  const animationStartRef = useRef()

  const [, api] = useSpring(() => ({
    onChange: state => {
      material.current.uniforms.uProg.value = state.value.number
    },
    config: { ...config.stiff },
    number: 1,
  }))

  useEffect(() => {
    async function fadeIn() {
      await api.set({ number: 0 })
      await api.start({
        number: 1,
        config: { duration: 100 },
        onStart: () => {
          animationStartRef.current = Date.now()
        },
      })
    }

    async function fadeOut(complete = false) {
      await api.set({ number: material.current.uniforms.uProg.value })
      await api.start({
        number: complete ? 0 : 0.3,
        config: {
          duration: 1200,
        },
        onRest: () => {
          animationStartRef.current = null
        },
      })
    }

    if (cameraMoving && mesh.current.position.z < camera.position.z) {
      fadeIn()
    } else {
      fadeOut()
    }
  }, [api, cameraMoving, camera])

  useFrame(state => {
    material.current.uniforms.uTime.value = state.clock.getElapsedTime()
    material.current.uniforms.uCameraDistanceZ.value = Math.abs(
      camera.position.z - mesh.current.position.z
    )
  })

  return (
    <mesh ref={mesh} {...props} geometry={geometry}>
      <Text
        font={font}
        position={[-0.6, 0.5, 0]}
        anchorX="left"
        rotation-z={-Math.PI / 2}
      >
        {formatLabel(text)}
      </Text>
      <imageMaterial ref={material} map={texture} />
    </mesh>
  )
}

export default Image
