import { useRef, useState } from "react"
import { animated, useSpring } from "@react-spring/web"

import atmoSoundSrc from "./../../assets/audio/atmo.mp3"
import atmoSoundSrc1 from "./../../assets/audio/atmo1.mp3"
import "./AudioPlayer.css"
import useStore from "../../store"
import { Toggle, content } from "./../../common"
import { easings } from "../../constants"

const REDUCED_VOLUME = 0.1
const FULL_VOLUME = 0.8

const AudioPlayer = ({ show }) => {
  const audioRef = useRef()
  const audioRef1 = useRef()
  const [mute, setMute] = useState(false)
  const labels = content.useContent({ path: "experience/audioPlayer" })

  const fullVolume = useStore(state => state.audio.full)

  useSpring({
    from: { volume: 0 },
    volume: fullVolume ? FULL_VOLUME : REDUCED_VOLUME,
    onChange: state => {
      audioRef.current.volume = state.value.volume.toFixed(2)
      audioRef1.current.volume = state.value.volume.toFixed(2)
    },
    config: { duration: 3000, easing: easings.easeOutQuad },
  })

  const itemTransitions = useSpring({
    opacity: show ? 1 : 0,
    y: show ? 0 : 32,
    config: { easing: easings.easeOutQuad },
  })

  return (
    <div className="overflow-hidden">
      <animated.div className="audio-player" style={itemTransitions}>
        <Toggle.Root
          onChange={state => setMute(state)}
          description="Toggle sound"
        >
          <Toggle.TextLabel onLabel={labels.unmute} offLabel={labels.mute} />
        </Toggle.Root>
      </animated.div>
      <audio
        ref={audioRef}
        preload="auto"
        autoPlay
        loop
        muted={mute}
        style={{ display: "none" }}
      >
        <source src={atmoSoundSrc} type={"audio/mp3"} />
      </audio>
      <audio
        ref={audioRef1}
        preload="auto"
        autoPlay
        loop
        muted={mute}
        style={{ display: "none" }}
      >
        <source src={atmoSoundSrc1} type={"audio/mp3"} />
      </audio>
    </div>
  )
}

export default AudioPlayer
