import { useTexture } from "@react-three/drei"
import { useEffect, useState } from "react"

import { allChaptersCount } from "../../constants"
import { utils } from "../../common"

const PRELOADING_COOL_DOWN_TIMEOUT = 5000

const preloadedChapters = []

const PreloadTextures = () => {
  const [preloadingChapter, setPreloadingChapter] = useState(1)

  utils.useTimeout(() => {
    if (preloadingChapter < allChaptersCount) {
      preloadedChapters.push(preloadingChapter)
      setPreloadingChapter(preloadingChapter + 1)
    }
  }, PRELOADING_COOL_DOWN_TIMEOUT)

  useEffect(() => {
    const preloadChapterImages = async () => {
      console.log("💾 start preload images for chapter:", preloadingChapter)
      const { modules } = await utils.chapterImagesRequireContextes(
        preloadingChapter
      )

      for (const imageModule of modules) {
        useTexture.preload(imageModule.default)
      }
    }

    if (!preloadedChapters.includes(preloadingChapter)) {
      preloadChapterImages()
    }
  }, [preloadingChapter])

  return null
}

export default PreloadTextures
