import { useRef } from "react"
import { animated, useSpring } from "@react-spring/web"

import useStore from "../../store"
import { allChaptersCount, easings } from "../../constants"
import { ProgressBar } from "../../common"
import "./ChapterProgress.css"

const ProgressForSingleChapter = ({
  currentChapter,
  paused,
  progressOfChapter,
  progress,
}) => {
  const lastProgress = useRef()

  const getConstantProgress = () => {
    if (progressOfChapter > currentChapter) {
      lastProgress.current = 0
    } else if (progressOfChapter < currentChapter) {
      lastProgress.current = 100
    }

    return lastProgress.current
  }

  return (
    <ProgressBar
      withAnimation={!paused}
      now={
        currentChapter === progressOfChapter ? progress : getConstantProgress()
      }
    />
  )
}

const ChapterProgress = ({ show }) => {
  const { index: chapterIndex } = useStore(state => state.chapter)
  const cameraProgress = useStore(state => state.cameraProgress)
  const paused = useStore(state => state.chapterTransitionActive)

  const itemTransitions = useSpring({
    opacity: show ? 1 : 0,
    y: show ? "0%" : "100%",
    delay: show ? 1200 : 0,
    config: { easing: easings.easeOutQuad },
  })

  return (
    <div className="chapter-progress overflow-hidden">
      <animated.div className="chapter-progress__items" style={itemTransitions}>
        {[...Array(allChaptersCount).keys()].map(chapter => (
          <ProgressForSingleChapter
            key={chapter}
            paused={paused}
            progressOfChapter={chapter + 1}
            currentChapter={chapterIndex}
            progress={cameraProgress}
          />
        ))}
      </animated.div>
    </div>
  )
}

export default ChapterProgress
