import { useEffect, useRef } from "react"

import { gridSpacing, trackingShot } from "../../../constants"
import useStore from "../../../store"
import { getCameraStartPos } from "../cameraUtils"
import useAnimatedTrackingShot from "./useAnimatedTrackingShot"

const EnterExperienceShot = ({ onFinished }) => {
  const previousChapterIndex = useRef(1)

  const { index: chapterIndex } = useStore(state => state.chapter)

  const cameraMoveApi = useAnimatedTrackingShot({ onFinished })

  useEffect(() => {
    if (chapterIndex === previousChapterIndex.current) return

    const isGoingBack = previousChapterIndex.current > chapterIndex

    cameraMoveApi.start({
      from: {
        z: isGoingBack
          ? gridSpacing.z
          : getCameraStartPos() + trackingShot.chapterSwitch.offsetToStartPos,
      },
      to: { z: getCameraStartPos() },
      onStart: () => {
        previousChapterIndex.current = chapterIndex
      },
    })
  }, [chapterIndex, cameraMoveApi])

  return null
}

export default EnterExperienceShot
