import React from "react"
import { Canvas } from "@react-three/fiber"

import Scene from "./Scene"

import PreloadTextures from "./PreloadTextures"
import { getCameraStartPos } from "./cameraUtils"

const CanvasContainer = () => {
  return (
    <Canvas
      legacy={true}
      dpr={[1, Math.min(window.devicePixelRatio, 2)]}
      onCreated={({ gl }) => gl.setClearColor("black", 0)}
      camera={{ position: [0, 0, getCameraStartPos()] }}
    >
      <Scene />
      <PreloadTextures />
    </Canvas>
  )
}

export default CanvasContainer
