import { useProgress } from "@react-three/drei"
import { useEffect } from "react"

import "./Container.css"
import ChapterSwitch from "./ChapterSwitch"
import ChapterTitle from "./ChapterTitle"
import ChapterProgress from "./ChapterProgress"
import CanvasContainer from "./../gl"
import useStore, {
  addToActiveLoading,
  removeFromActiveLoading,
} from "./../../store"
import Epilog from "./Epilog"
import AudioPlayer from "./AudioPlayer"

const Container = () => {
  const inExperience = useStore(state => state.inExperience)
  const cameraAtMinPos = useStore(state => state.cameraAtMinPos)
  const chapterTransitionActive = useStore(
    state => state.chapterTransitionActive
  )
  const showOverlayElements = !chapterTransitionActive && !cameraAtMinPos

  return (
    <>
      {inExperience && (
        <>
          <div className="experience-overlay">
            <div className="experience-overlay__aside experience-overlay__aside--1">
              <ChapterTitle show={showOverlayElements} />
            </div>
            <div className="experience-overlay__main">
              <Epilog />
            </div>
            <div className="experience-overlay__aside experience-overlay__aside--2">
              <AudioPlayer show={showOverlayElements} />
            </div>
            <div className="experience-overlay__aside experience-overlay__aside--3">
              <ChapterProgress show={showOverlayElements} />
            </div>
          </div>
          <ChapterSwitch />
          <Spinner />
        </>
      )}
      <div className="experience-canvas">
        <CanvasContainer />
      </div>
    </>
  )
}

const Spinner = () => {
  const active = useProgress(state => state.active)

  useEffect(() => {
    if (active) {
      addToActiveLoading("canvasContainer")
    } else {
      removeFromActiveLoading("canvasContainer")
    }
  }, [active])

  return null
}

export default Container
