import { useFrame, useThree } from "@react-three/fiber"
import { useRef } from "react"
import { Quaternion, Euler, MathUtils } from "three"
import { useControls } from "leva"

import Controls from "./Controls"
import Chapter from "./Chapter"
import { gridSpacing, itemPerColumn, itemsPerRow } from "./../../constants"
import useStore from "./../../store"
import { ChapterSwitchShot } from "./trackingShots"

const rotationEuler = new Euler(0, 0, 0)
const rotationQuaternion = new Quaternion(0, 0, 0, 0)

const Scene = () => {
  const { camera, viewport } = useThree(state => ({
    camera: state.camera,
    setCanvasProp: state.set,
    viewport: state.viewport,
  }))

  const fogControls = useControls("fog", {
    show: true,
    color: "#5766b1",
    startingAt: 2,
    endingAt: 42,
  })

  useControls("camera", {
    nearPlaneClippingPos: {
      value: 0.5,
      min: 0.1,
      max: 5,
      step: 0.1,
      onChange: val => {
        camera.near = Math.round(val)
      },
    },
  })

  const imageControls = useControls("image", {
    size: {
      value: 1,
      min: 1,
      max: 5,
      step: 1,
    },
  })

  const chapter = useStore(state => state.chapter)

  const group = useRef()

  const { usesTouch } = useStore(state => state.clientProfile)
  useFrame(({ mouse }) => {
    if (!group.current || usesTouch) return

    const x = MathUtils.clamp((mouse.x / viewport.width) * 0.3, 0.0001, 0.0009)
    const y = MathUtils.clamp((mouse.y / viewport.height) * 0.3, 0.0001, 0.0009)

    rotationEuler.set(y * -1, x, 0)
    rotationQuaternion.setFromEuler(rotationEuler)
    group.current.quaternion.slerp(rotationQuaternion, 0.1)
  })

  return (
    <>
      {fogControls.show && (
        <fog
          attach="fog"
          args={[
            fogControls.color,
            fogControls.startingAt,
            fogControls.endingAt,
          ]}
        />
      )}
      <Controls />
      <group ref={group}>
        <group
          position={[
            -Math.floor(
              (itemPerColumn * imageControls.size +
                (itemPerColumn - 1) * gridSpacing.x) /
                2
            ),
            -Math.floor(
              (itemsPerRow * imageControls.size +
                (itemPerColumn - 1) * gridSpacing.y) /
                2
            ),
            gridSpacing.z,
          ]}
        >
          <Chapter
            images={chapter.images}
            imageSize={imageControls.size}
            annotations={chapter.captions}
          />
          <ChapterSwitchShot />
        </group>
      </group>
    </>
  )
}

export default Scene
