import { animated, useTransition } from "@react-spring/web"

import { useContent } from "../../common/content"
import { allChaptersCount, easings } from "../../constants"
import useStore, { turnDownAudioVolume, setAudioFullVolume } from "../../store"
import "./Epilog.css"

const Epilog = () => {
  const { title, copy } = useContent({ path: "experience/epilog" })
  const cameraAtMinPos = useStore(state => state.cameraAtMinPos)
  const chapterTransitionActive = useStore(
    state => state.chapterTransitionActive
  )
  const { index: chapterIndex } = useStore(state => state.chapter)
  const show =
    !chapterTransitionActive &&
    cameraAtMinPos &&
    chapterIndex === allChaptersCount

  const containerTransitions = useTransition(show, {
    from: { opacity: 0 },
    enter: { opacity: 1, delay: 700 },
    leave: { opacity: 0 },
    config: { duration: 1400, easing: easings.easeOutQuad },
    onRest: state => {
      if (show) {
        turnDownAudioVolume()
      } else {
        setAudioFullVolume()
      }
    },
  })

  return (
    <>
      {containerTransitions(
        (styles, item) =>
          item && (
            <animated.div className="epilog" style={styles}>
              <h2 className="epilog__title">{title}</h2>
              <div className="epilog__scroll-container">
                <p className="epilog__copy copy-text">{copy}</p>
              </div>
            </animated.div>
          )
      )}
    </>
  )
}

export default Epilog
