import { useSpring } from "@react-spring/three"
import { useThree } from "@react-three/fiber"

import { easings } from "../../../constants"
import {
  setCameraMoving,
  setCameraHalt,
  setChapterTransition,
  setCameraPositionBounds,
} from "../../../store"
import { getCameraStartPos, isCameraAtMinOrMaxPosZ } from "../cameraUtils"

const useAnimatedTrackingShot = ({ onFinished }) => {
  const { camera } = useThree()
  const [, cameraMoveApi] = useSpring(() => ({
    from: { x: 0, y: 0, z: 0 },
    onStart: () => {
      setCameraMoving()
    },
    onRest: () => {
      setChapterTransition(false)
      setCameraHalt()

      const { atMaxPos, atMinPos } = isCameraAtMinOrMaxPosZ(getCameraStartPos())

      setCameraPositionBounds(atMinPos, atMaxPos)

      if (onFinished) {
        onFinished()
      }
    },
    onChange: state => {
      camera.position.set(state.value.x, state.value.y, state.value.z)
    },
    config: { easing: easings.easeOutQuad, duration: 1200 },
  }))

  return cameraMoveApi
}

export default useAnimatedTrackingShot
