import { gridSpacing, itemsPerSegment } from "../../constants"

export function getCameraStartPos() {
  return gridSpacing.z * itemsPerSegment + gridSpacing.z
}

export function getCameraEndPos() {
  return gridSpacing.z
}

export function isCameraAtMinOrMaxPosZ(cameraPosZ) {
  const roundedPosZ = Math.round(cameraPosZ)
  const cameraStartPos = getCameraStartPos()
  const cameraEndPos = getCameraEndPos()

  const results = {
    atMinPos: roundedPosZ <= cameraEndPos,
    atMaxPos: roundedPosZ >= cameraStartPos,
  }

  return results
}

export function cameraOverallProgress(cameraPosZ, cameraTravelDistance) {
  const roundedPosZ = Math.round(cameraPosZ)

  return 100 - (roundedPosZ / cameraTravelDistance) * 100
}
